//! Actual checked growth/first-error and closed direct ALLOW usage contracts.
#[path="../fixtures/native-expiry-workspace/fixture.rs"]mod fixture;
use crate::{captured_raw_tree_pages::Policy,captured_generator_budget::Budget,captured_raw_file::{Config,RawPolicyViews},captured_reactive_reads::Failure};
use std::{path::Path,sync::Arc,io};
struct Pages<'a>{root:&'a Path,rows:Vec<(String,dm_preprocess::SourceText)>,budget:Arc<Budget>,stop:bool}
impl crate::reactive_raw_policy_pages::RawPolicyPages for Pages<'_>{fn for_each(&self,visit:&mut dyn FnMut(&str,RawPolicyViews<'_>)->Result<bool,Failure>)->Result<bool,Failure>{if self.stop{return Ok(false)}for(relative,text)in &self.rows{if !crate::captured_raw_file::with_original_policy_file(self.root,&self.root.join(relative),text.clone(),0,&self.budget,visit)?{return Ok(false)}}Ok(true)}}
#[test]fn expiry_checked_each_original_pass_refuses_before_growth_preserves_1450_and_recovers(){let root=std::env::current_dir().unwrap().join("expiry-checked-original-source");let b=Budget::new(512*1024*1024).unwrap();let text=format!("/obj/control/proc/tick()\n{}","\tif(world.time > last_at) return\n\tstored = world.time\n\tmember.last = TIME_NOW()\n\tCOOLDOWN_RUNNING(src, missing)\n".repeat(512));crate::captured_raw_file::with_original_policy_file(&root,&root.join("code/expiry.dm"),text.into(),0,&b,&mut|_,views|{let file=views.source_file()?;for which in 0..3{let tiny=Budget::new(std::mem::size_of::<Budget>()+2*std::mem::size_of::<usize>()).unwrap();let mut keep=crate::captured_allow_annotations::Operation{budget:&tiny,poll:&||Ok(())};let mut temp=crate::captured_allow_annotations::Operation{budget:&b,poll:&||Ok(())};let denied=match which{0=>crate::expiry_policy::pass_compares_using(file,None,&mut keep,&mut|_,_|Ok(false)).map(|_|()),1=>crate::expiry_policy::pass_writes_using(file,&mut keep,&mut temp).map(|_|()),_=>crate::expiry_policy::pass_at_writes_using(file,&mut keep,&mut temp).map(|_|())};assert!(matches!(denied,Err(Failure::Operational(ref e))if e.kind()==io::ErrorKind::OutOfMemory));let calls=std::cell::Cell::new(0usize);let poll=||{let next=calls.get()+1;calls.set(next);if next==32{Err(io::Error::from_raw_os_error(1450))}else{Ok(())}};let mut keep=crate::captured_allow_annotations::Operation{budget:&b,poll:&poll};let result=match which{0=>crate::expiry_policy::pass_compares_using(file,None,&mut keep,&mut|_,_|Ok(false)).map(|_|()),1=>crate::expiry_policy::pass_writes_using(file,&mut keep,&mut temp).map(|_|()),_=>crate::expiry_policy::pass_at_writes_using(file,&mut keep,&mut temp).map(|_|())};assert!(matches!(result,Err(Failure::Operational(ref e))if e.raw_os_error()==Some(1450)));assert_eq!(calls.get(),32);let mut keep=crate::captured_allow_annotations::Operation{budget:&b,poll:&||Ok(())};match which{0=>assert_eq!(crate::expiry_policy::pass_compares_using(file,None,&mut keep,&mut|_,_|Ok(false))?.len(),512),1=>{let facts=crate::expiry_policy::pass_writes_using(file,&mut keep,&mut temp)?;assert_eq!(facts.writes.len(),512);assert_eq!(facts.uses.len(),512);},_=>assert_eq!(crate::expiry_policy::pass_at_writes_using(file,&mut keep,&mut temp)?.len(),512)}}Ok(true)}).unwrap();}
#[test]fn expiry_incomplete_data_refuses_and_direct_cooldown_trace_does_not_expand_registry_metadata(){assert!(!Policy::Expiry.metadata().allow.contains(&"cooldown"));assert!(Policy::Expiry.permits_used_allow("cooldown"));assert!(!Policy::LookEffects.permits_used_allow("cooldown"));assert!(!Policy::Expiry.permits_used_allow("scheduler"));assert!(!Policy::Expiry.permits_used_allow("cooldown_unported"));assert!(Policy::from_name("sys/expiry_unported").is_none());let root=std::env::current_dir().unwrap().join("expiry-incomplete-data");let b=Budget::new(256*1024*1024).unwrap();let config=Config::capture(crate::captured_raw_policy::Configuration::Captured(fixture::configuration("expiry",0).as_bytes())).unwrap();let rows=fixture::files("expiry",0).into_iter().filter(|(p,_)|Policy::Expiry.selects_path(p)).map(|(p,s)|{let original=dm_preprocess::AcquiredSource::from_original_bytes(s.into_bytes(),());(p.into(),original.lease().source_text().clone())}).collect();let mut pages=Pages{root:&root,rows,budget:Arc::clone(&b),stop:true};assert!(matches!(crate::captured_expiry_pages::collect(&pages,&config,&b,&||Ok(())),Err(Failure::Unsupported(message))if message.contains("EOF")));pages.stop=false;let data=crate::captured_expiry_pages::collect(&pages,&config,&b,&||Ok(())).unwrap();assert!(!data.sites().is_empty());assert!(data.allow_used().iter().any(|u|u.name=="cooldown"));assert!(data.allow_used().iter().any(|u|u.name=="sys_world_time_expiry"));}
